/**
 * ODE checks: representative equations for SymPy's dsolve hints, compared
 * with the output of SymPy (compat/ode-checks.json, generated by
 * compat/gen-ode-checks.py). Reported separately in compat/REPORT.md.
 */

import { readFileSync } from 'node:fs';
import * as sj from '../packages/symjs/src';
import { Expr } from '../packages/symjs/src';

type OdeCheck = { hint: string; eq: string; ics?: [string, string][]; expected: string };
export type OdeCheckResult = OdeCheck & { got: string; pass: boolean };

export function runOdeChecks(): OdeCheckResult[] {
  const data = JSON.parse(readFileSync(new URL('./ode-checks.json', import.meta.url), 'utf8')) as { checks: OdeCheck[] };
  const f = sj.Function('f');
  const x = new sj.Sym('x');
  const fx = f(x);
  return data.checks.map((c) => {
    let got: string;
    try {
      const eq = sj.parse(c.eq);
      const ics = c.ics?.map(([k, v]) => [icsKey(k, fx, x), sj.parse(v)] as [Expr, Expr]);
      const r = sj.dsolve(eq, fx, ics ? { ics } : {});
      got = Array.isArray(r) ? `[${r.map(String).join(', ')}]` : String(r);
    } catch (e) {
      got = `error: ${(e as Error).message}`;
    }
    return { ...c, got, pass: got === c.expected };
  });
}

/** f(0) or Subs(Derivative(f(x), x), x, 0) written as SymPy prints them. */
function icsKey(k: string, fx: Expr, x: sj.Sym): Expr {
  const m = /^Subs\(Derivative\(f\(x\), (.*)\), x, (.*)\)$/.exec(k);
  if (m) {
    const order = m[1]!.split(',').length;
    const at = sj.parse(m[2]!);
    return sj.derivative(sj.Function('f')(at), [[x, order]]);
  }
  void fx;
  return sj.parse(k);
}
